"use client";
import { useActionState } from "react";
import { changePasswordAction, type AuthActionState } from "@/app/auth/actions";
const initial: AuthActionState = { ok: false };
export function AccountSecurity({ hasPassword, vi }: { hasPassword: boolean; vi: boolean }) { const [state, action, pending] = useActionState(changePasswordAction, initial); return <form action={action} className="mt-6 space-y-3 border-t border-slate-100 pt-6"><h3 className="font-black">{hasPassword ? (vi ? "Đổi mật khẩu" : "Change password") : (vi ? "Đặt mật khẩu" : "Set password")}</h3>{hasPassword ? <input className="w-full rounded-lg border px-3 py-2.5" name="currentPassword" placeholder={vi ? "Mật khẩu hiện tại" : "Current password"} required type="password" /> : null}<input className="w-full rounded-lg border px-3 py-2.5" minLength={10} name="password" placeholder={vi ? "Mật khẩu mới (10+ ký tự)" : "New password (10+ characters)"} required type="password" /><input className="w-full rounded-lg border px-3 py-2.5" minLength={10} name="confirmPassword" placeholder={vi ? "Xác nhận mật khẩu" : "Confirm password"} required type="password" /><button className="rounded-lg bg-teal-700 px-4 py-2.5 font-bold text-white" disabled={pending}>{vi ? "Lưu mật khẩu" : "Save password"}</button>{state.error ? <p className="text-sm text-red-700">{state.error}</p> : null}{state.message ? <p className="text-sm text-emerald-700">{state.message}</p> : null}</form>; }
